package org.jfree.data.statistics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.PublicCloneable;
import org.jfree.data.KeyedObjects2D;
import org.jfree.data.Range;
import org.jfree.data.RangeInfo;
import org.jfree.data.general.AbstractDataset;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class DefaultBoxAndWhiskerCategoryDataset_add_TriageGen0Test {

    private DefaultBoxAndWhiskerCategoryDataset dataset;

    @Before
    public void setUp() {
        dataset = new DefaultBoxAndWhiskerCategoryDataset();
    }

    @Test
    public void testAddFirstItem_SetsMinAndMax() {
        // Create item with outliers
        BoxAndWhiskerItem item = new BoxAndWhiskerItem(
                Arrays.asList(10.0, 12.0, 14.0), // regular values
                11.0, // Q1
                13.0, // Q3
                12.0, // median
                5.0,  // min outlier
                20.0  // max outlier
        );

        dataset.add(item, "Row1", "Col1");

        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(20.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddWithNaNOutliers_SetsMinAndMaxFromRegularValues() {
        // Based on code logic: if outlier is null, minval/maxval becomes NaN
        // If maximumRangeValue is NaN, it takes maxval (which is NaN)
        // This test checks the logic flow for null outliers
        BoxAndWhiskerItem item = new BoxAndWhiskerItem(
                Arrays.asList(10.0, 12.0, 14.0),
                11.0, 13.0, 12.0,
                null, // min outlier
                null  // max outlier
        );

        dataset.add(item, "Row1", "Col1");

        // Since maxval is NaN, maximumRangeValue becomes NaN
        // Since minval is NaN, minimumRangeValue becomes NaN
        // Range bounds will be NaN
        assertEquals(Double.NaN, dataset.getRangeLowerBound(true), 0.0);
        assertEquals(Double.NaN, dataset.getRangeUpperBound(true), 0.0);
    }

    @Test
    public void testAddUpdatesMaxWhenHigher() {
        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(
                Arrays.asList(10.0), 10.0, 10.0, 10.0, 5.0, 15.0);
        dataset.add(item1, "R1", "C1");

        BoxAndWhiskerItem item2 = new BoxAndWhiskerItem(
                Arrays.asList(20.0), 20.0, 20.0, 20.0, 18.0, 25.0);
        dataset.add(item2, "R2", "C2");

        assertEquals(25.0, dataset.getRangeUpperBound(true), 0.001);
        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001);
    }

    @Test
    public void testAddUpdatesMinWhenLower() {
        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(
                Arrays.asList(10.0), 10.0, 10.0, 10.0, 5.0, 15.0);
        dataset.add(item1, "R1", "C1");

        BoxAndWhiskerItem item2 = new BoxAndWhiskerItem(
                Arrays.asList(20.0), 20.0, 20.0, 20.0, 2.0, 25.0);
        dataset.add(item2, "R2", "C2");

        assertEquals(2.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(15.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddTriggersUpdateBounds_WhenMatchingMaxLocation() {
        // To trigger updateBounds(), we need to add an item to the same row/col 
        // that currently holds the maximum or minimum.

        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(
                Arrays.asList(10.0), 10.0, 10.0, 10.0, 5.0, 100.0);
        dataset.add(item1, "R1", "C1"); // Max is at (0,0)

        // Add item to same location but with lower max value
        // This triggers: if ((this.maximumRangeValueRow == r && ...)) { updateBounds(); }
        BoxAndWhiskerItem item2 = new BoxAndWhiskerItem(
                Arrays.asList(10.0), 10.0, 10.0, 10.0, 5.0, 50.0);
        dataset.add(item2, "R1", "C1");

        // After updateBounds (assuming it recalculates from all data), 
        // the max should still be 100 if updateBounds works correctly.
        // Even if we don't know the exact implementation of updateBounds, 
        // the branch is covered by hitting this condition.
        assertNotNull(dataset.getRangeBounds(true));
    }

    @Test
    public void testAddTriggersUpdateBounds_WhenMatchingMinLocation() {
        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(
                Arrays.asList(10.0), 10.0, 10.0, 10.0, 5.0, 100.0);
        dataset.add(item1, "R1", "C1"); // Min is at (0,0)

        // Add item to same location
        BoxAndWhiskerItem item2 = new BoxAndWhiskerItem(
                Arrays.asList(10.0), 10.0, 10.0, 10.0, 1.0, 100.0);
        dataset.add(item2, "R1", "C1");

        assertNotNull(dataset.getRangeBounds(true));
    }

    @Test
    public void testAddDoesNotUpdateMaxWhenLower() {
        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(
                Arrays.asList(10.0), 10.0, 10.0, 10.0, 5.0, 100.0);
        dataset.add(item1, "R1", "C1");

        BoxAndWhiskerItem item2 = new BoxAndWhiskerItem(
                Arrays.asList(10.0), 10.0, 10.0, 10.0, 5.0, 50.0);
        dataset.add(item2, "R2", "C2");

        // Max should remain 100.0
        assertEquals(100.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddDoesNotUpdateMinWhenHigher() {
        BoxAndWhiskerItem item1 = new BoxAndWhiskerItem(
                Arrays.asList(10.0), 10.0, 10.0, 10.0, 5.0, 100.0);
        dataset.add(item1, "R1", "C1");

        BoxAndWhiskerItem item2 = new BoxAndWhiskerItem(
                Arrays.asList(10.0), 10.0, 10.0, 10.0, 10.0, 100.0);
        dataset.add(item2, "R2", "C2");

        // Min should remain 5.0
        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001);
    }
}
